// Insertion Sort implementation
function insertionSort(arr) {
  const n = arr.length;

  for (let i = 1; i < n; i++) {
    let key = arr[i];
    let j = i - 1;

    while (j >= 0 && arr[j] > key) {
      arr[j + 1] = arr[j];
      j--;
    }

    arr[j + 1] = key;
  }

  return arr;
}

// Example usage
const arr = [12, 11, 13, 5, 6];
console.log('Original:', arr);
insertionSort(arr);
console.log('Sorted:', arr); 
// [5, 6, 11, 12, 13]
